class Point:
    def __repr__(self):
        return "Point(1, 2)"

    def __str__(self):
        return "(1, 2)"

p = Point()
print(p)
print([p])

class Resp:
    def __init__(self, code):
        self.code = code

a = Resp(200)
b = Resp(200)
print(a == b, a == a)

class Item:
    def __init__(self, sku):
        self.sku = sku

    def __eq__(self, other):
        return self.sku == other.sku

print(Item("a1") == Item("a1"))

class Key:
    def __init__(self, k):
        self.k = k

    def __eq__(self, other):
        return self.k == other.k

print({Key(1), Key(2)})

class Response:
    def __init__(self, status):
        self.status = status

    def __bool__(self):
        return self.status < 400

r = Response(404)
print(bool(r), "bad" if not r else "ok")

class Batch:
    def __len__(self):
        return 0

b = Batch()
print(len(b), bool(b))

class Deck:
    def __getitem__(self, i):
        if i > 2:
            raise IndexError
        return i * 10

d = Deck()
print(d[1])
print(list(d))

class Money:
    def __init__(self, c):
        self.c = c

    def __add__(self, other):
        return Money(self.c + other.c)

m = Money(150) + Money(50)
print(m.c)

class ApiResp:
    def __init__(self, body):
        self.body = body

    def __contains__(self, key):
        return key in self.body

r = ApiResp({"id": 7})
print("id" in r, "name" in r)

class Timer:
    def __enter__(self):
        print("start")
        return self

    def __exit__(self, *args):
        print("stop")

with Timer():
    print("work")

class Score:
    def __init__(self, v):
        self.v = v

a = Score(1)
print(a < Score(2))
